# Combined structure for easy access
# MISSION_POOL[category][slot] = list of missions
MISSION_POOL = {
	0: {  # Daily
		0: DAILY_SLOT_0,
		1: DAILY_SLOT_1,
		2: DAILY_SLOT_2,
	},
	1: {  # Weekly
		0: WEEKLY_SLOT_0,
		1: WEEKLY_SLOT_1,
		2: WEEKLY_SLOT_2,
	},
}

def GetMissionPoolByCategory(category):
	"""Get all missions for a category (0=Daily, 1=Weekly)"""
	if category not in MISSION_POOL:
		return {}
	return MISSION_POOL[category]

def GetMissionPoolBySlot(category, slot):
	"""Get missions for a specific slot"""
	if category not in MISSION_POOL:
		return []
	if slot not in MISSION_POOL[category]:
		return []
	return MISSION_POOL[category][slot]

def GetFilteredMissions(category, playerLevel):
	"""Get all missions for a category filtered by player level"""
	result = []
	if category not in MISSION_POOL:
		return result

	for slot, missions in MISSION_POOL[category].items():
		for mission in missions:
			missionType, target, count, minLevel, maxLevel = mission
			if minLevel <= playerLevel <= maxLevel:
				result.append((slot, missionType, target, count, minLevel, maxLevel))

	return result

def GetAllFilteredMissions(playerLevel):
	"""Get all missions (daily + weekly) filtered by player level"""
	return {
		0: GetFilteredMissions(0, playerLevel),
		1: GetFilteredMissions(1, playerLevel),
	}
